{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_section",
        "revenue_expenses_section",
        "net_profit_section",
        "highlights_section"
      ]
    },
    "overview_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "overview_heading_stack",
        "overview_description"
      ]
    },
    "overview_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "overview_icon",
        "overview_title"
      ]
    },
    "overview_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000186_01_1_graph-up.svg"
      },
      "children": []
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "Quarterly Sales Performance Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_description": {
      "type": "Text",
      "props": {
        "text": "This report summarizes the monthly financial performance, including revenue, expenses, and net profit, for the recent quarter.",
        "variant": "body"
      },
      "children": []
    },
    "revenue_expenses_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "revenue_expenses_heading_stack",
        "revenue_expenses_description",
        "revenue_expenses_table"
      ]
    },
    "revenue_expenses_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "revenue_expenses_icon",
        "revenue_expenses_title"
      ]
    },
    "revenue_expenses_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000186_01_1_graph-up.svg"
      },
      "children": []
    },
    "revenue_expenses_title": {
      "type": "Text",
      "props": {
        "text": "Monthly Revenue and Expenses Trend",
        "variant": "h2"
      },
      "children": []
    },
    "revenue_expenses_description": {
      "type": "Text",
      "props": {
        "text": "The data below shows the trend of revenue and expenses over the months.",
        "variant": "body"
      },
      "children": []
    },
    "revenue_expenses_table": {
      "type": "Table",
      "props": {
        "title": "Monthly Revenue and Expenses",
        "columns": [
          {
            "key": "Month",
            "label": "Month"
          },
          {
            "key": "Revenue",
            "label": "Revenue"
          },
          {
            "key": "Expenses",
            "label": "Expenses"
          }
        ],
        "rows": [
          {
            "Month": "Jan",
            "Revenue": 10000,
            "Expenses": 7000
          },
          {
            "Month": "Feb",
            "Revenue": 12000,
            "Expenses": 7500
          },
          {
            "Month": "Mar",
            "Revenue": 11000,
            "Expenses": 6800
          },
          {
            "Month": "Apr",
            "Revenue": 13000,
            "Expenses": 8000
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": ["Revenue", "Expenses"]
      },
      "children": []
    },
    "net_profit_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "net_profit_heading_stack",
        "net_profit_description",
        "net_profit_table"
      ]
    },
    "net_profit_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "net_profit_icon",
        "net_profit_title"
      ]
    },
    "net_profit_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000186_01_2_bar-chart.svg"
      },
      "children": []
    },
    "net_profit_title": {
      "type": "Text",
      "props": {
        "text": "Monthly Net Profit Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "net_profit_description": {
      "type": "Text",
      "props": {
        "text": "This data provides the net profit for each month, calculated as Revenue minus Expenses.",
        "variant": "body"
      },
      "children": []
    },
    "net_profit_table": {
      "type": "Table",
      "props": {
        "title": "Monthly Net Profit",
        "columns": [
          {
            "key": "Month",
            "label": "Month"
          },
          {
            "key": "Net Profit",
            "label": "Net Profit"
          }
        ],
        "rows": [
          {
            "Month": "Jan",
            "Net Profit": 3000
          },
          {
            "Month": "Feb",
            "Net Profit": 4500
          },
          {
            "Month": "Mar",
            "Net Profit": 4200
          },
          {
            "Month": "Apr",
            "Net Profit": 5000
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": ["Net Profit"]
      },
      "children": []
    },
    "highlights_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "highlights_title",
        "highlights_description"
      ]
    },
    "highlights_title": {
      "type": "Text",
      "props": {
        "text": "Profit Highlights",
        "variant": "h2"
      },
      "children": []
    },
    "highlights_description": {
      "type": "Text",
      "props": {
        "text": "April recorded the highest net profit of $5,000, indicating strong performance in that month.",
        "variant": "body"
      },
      "children": []
    }
  }
}
